export function exerciseBankTasks(state) {
  const harness = createExerciseBankHarness(state);
  const handlers = {
    prepare: () => harness.prepare(),
    revoke: (input) => harness.revoke(input, input),
    archive: (input) => harness.archive(input),
    snapshot: (input) => harness.snapshot(input),
    async performance(input) {
      assert.ok(['list', 'detail'].includes(input.surface));
      assert.ok(Array.isArray(input.samples) && input.samples.length <= 50);
      assert.ok(
        input.samples.every(
          (sample) =>
            Number.isFinite(sample.durationMs) && sample.durationMs >= 0,
        ),
      );
      assert.ok(
        Number.isFinite(input.firstNavigationMs) &&
          input.firstNavigationMs >= 0,
      );
      const sorted = input.samples
        .map((sample) => sample.durationMs)
        .sort((a, b) => a - b);
      const p95Ms = sorted.length
        ? sorted[Math.ceil(sorted.length * 0.95) - 1]
        : null;
      const passed =
        input.firstNavigationValid === true &&
        input.samples.length === 50 &&
        input.samples.every((sample) => sample.valid === true) &&
        p95Ms < 3000;
      await report(
        `exercise-bank-ui-${input.surface}`,
        {
          status: passed ? 'passed' : 'failed',
          surface: input.surface,
          firstNavigationMs: input.firstNavigationMs,
          firstNavigationValid: input.firstNavigationValid,
          samples: input.samples,
          p95Ms,
          percentile: 'nearest-rank',
          concurrency: 1,
          environment:
            'LAB TEST Chrome production build; authenticated navigation; services already started; first navigation separate from 50 warm samples',
          capacity: { exercises: 25, versions: 25, uses: 25 },
        },
        'imp-06',
      );
      return { passed, p95Ms, samples: input.samples.length };
    },
  };
  return Object.fromEntries(
    Object.entries(handlers).map(([name, handler]) => [
      `bank:${name}`,
      async (input) => {
        try {
          return await handler(input ?? {});
        } catch (error) {
          const code =
            typeof error?.code === 'string' &&
            /^[A-Z0-9_]{3,60}$/.test(error.code)
              ? error.code
              : 'FIXTURE_FAILURE';
          const directory = resolve('.local/evidence/imp-06');
          await mkdir(directory, { recursive: true });
          await writeFile(
            resolve(directory, 'exercise-bank-fixture-error.json'),
            JSON.stringify(
              {
                task: name,
                code,
                constraint:
                  typeof error?.constraint === 'string' &&
                  /^[a-z0-9_]+$/.test(error.constraint)
                    ? error.constraint
                    : null,
              },
              null,
              2,
            ),
            { mode: 0o600 },
          );
          throw safeTaskFailure(name, code);
        }
      },
    ]),
  );
}
